		void ActionsMenuItem_Popup(object sender, EventArgs e)
		{
			UpdateBOMMenuItemState();
		}

		void UpdateBOMMenuItemState()
		{
			foreach (MenuItem item in ActionsMenuItem.MenuItems)
			{
				var bomItem = item as BOMMenuItem;
				if (bomItem != null)
				{
					bomItem.UpdateCheckedAndEnabledStateForAllLines();
					break;
				}
			}
		}

