		#region INotificationSubscriberQueryUser Members

		void INotificationSubscriberQueryUser.QueryUser(IQueryUserEventArgs e)
		{
			switch (e)
			{
				case AssemblyConfirmationQueryUserEventArgs assemblyConfirmationArgs:
					var receive = Docket?.Receive;
					if (receive != null)
					{
						try
						{
							// no reason for the receive to call validation while bound to the Confirmation Dialog
							receive.Factory.SuspendValidation();

							using (var dialog = new WhsWorkOrderAssemblyConfirmationDialog(receive))
							{
								assemblyConfirmationArgs.Response = ZFormModaliser.ShowDialogWithoutDispose(dialog) == DialogResult.OK;
							}
						}
						finally
						{
							receive.Factory.ResumeValidation();
						}
					}
					break;
				default:
					WhsNotificationSubscriberGuiHelper.QueryUser(e);
					break;
			}
		}

